#!/usr/bin/env node
/**
 * A small command-line client for any UHP server.
 *
 * Reads the server and token from `--url` / `--key`, or from UHP_BASE_URL / UHP_API_KEY.
 */
import { HarnessRouter, UhpError } from './index.js';

const USAGE = `harnessrouter — a command-line client for the Unified Harness Protocol

  harnessrouter discover                    what the server is, and what it supports
  harnessrouter harnesses                   list configured harnesses
  harnessrouter models [<harness-id>]       list models, optionally for one harness
  harnessrouter run <prompt>                run a task and print the result
  harnessrouter stream <prompt>             run a task and print output as it happens
  harnessrouter get <response-id>           read a task back
  harnessrouter cancel <response-id>        stop a running task
  harnessrouter sessions                    list sessions

Options
  --url <url>          server root        (env UHP_BASE_URL, default http://localhost:3000)
  --key <token>        bearer token       (env UHP_API_KEY)
  --harness <id>       configured harness to run the work
  --model <id>         model to use
  --continue <resp-id> continue the session that produced this response
  --json               print raw JSON rather than a summary
`;

function parseArgs(argv) {
  const positional = [];
  const flags = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg.startsWith('--')) {
      const name = arg.slice(2);
      if (name === 'json') flags.json = true;
      else flags[name] = argv[++i];
    } else positional.push(arg);
  }
  return { positional, flags };
}

async function main() {
  const { positional, flags } = parseArgs(process.argv.slice(2));
  const [command, ...rest] = positional;
  if (!command || flags.help) {
    process.stdout.write(USAGE);
    return;
  }

  const client = new HarnessRouter({
    baseUrl: flags.url || process.env.UHP_BASE_URL || 'http://localhost:3000',
    apiKey: flags.key || process.env.UHP_API_KEY || '',
  });

  const print = (value) => process.stdout.write(`${JSON.stringify(value, null, 2)}\n`);
  const taskOptions = {
    harnessId: flags.harness,
    model: flags.model,
    previousResponseId: flags.continue,
  };

  switch (command) {
    case 'discover':
      return print(await client.discover());

    case 'harnesses': {
      const harnesses = await client.harnesses();
      if (flags.json) return print(harnesses);
      if (harnesses.length === 0) return process.stdout.write('No harnesses configured.\n');
      for (const h of harnesses) {
        process.stdout.write(`${h.id}  ${h.name}  [${h.base}]  ${h.defaultModel || ''}\n`);
      }
      return;
    }

    case 'models':
      return print(rest[0] ? await client.harnessModels(rest[0]) : await client.models());

    case 'run': {
      const response = await client.run(rest.join(' '), taskOptions);
      if (flags.json) return print(response);
      const { outputText } = await import('harnessclientprotocol');
      process.stdout.write(`${outputText(response)}\n`);
      process.stderr.write(`\n[${response.status}] ${response.id}\n`);
      return;
    }

    case 'stream': {
      let responseId = null;
      for await (const event of client.stream(rest.join(' '), taskOptions)) {
        if (flags.json) print(event);
        else if (event.type === 'response.output_text.delta') process.stdout.write(event.delta ?? '');
        if (event.type === 'response.created') responseId = event.response?.id ?? null;
        if (event.type.startsWith('response.') && event.response?.status && event.response.status !== 'in_progress') {
          process.stderr.write(`\n[${event.response.status}] ${event.response.id ?? responseId}\n`);
        }
      }
      return;
    }

    case 'get':
      return print(await client.getResponse(rest[0]));

    case 'cancel':
      return print(await client.cancel(rest[0]));

    case 'sessions':
      return print(await client.sessions({ limit: Number(flags.limit) || 20 }));

    default:
      process.stderr.write(`Unknown command: ${command}\n\n${USAGE}`);
      process.exitCode = 2;
  }
}

main().catch((error) => {
  if (error instanceof UhpError) {
    process.stderr.write(`${error.type || 'error'} / ${error.code || error.status}: ${error.message}\n`);
    if (error.param) process.stderr.write(`  at ${error.param}\n`);
    if (error.retryable) process.stderr.write('  this one is worth retrying\n');
  } else {
    process.stderr.write(`${error.message}\n`);
  }
  process.exitCode = 1;
});
